export async function dispatchTempestuousPluginLandingOriginal(ctx,operation,p,principal){const api=damageZeroPorts();if(operation==='prepare')return prepareTempestuousPluginLandingOriginal(ctx,p,principal,api);if(operation==='dice')return recordTempestuousPluginLandingOriginalDice(ctx,p,principal,api);if(operation==='inspect')return inspectTempestuousPluginLandingOriginal(ctx,p,principal,api);if(operation==='read')return readTempestuousPluginLandingOriginal(ctx,p,principal,api);return{ok:false,status:404,error:'tempestuous-plugin-landing:operation-required'}}
