/** Called only inside the shared append lock, before any queue write. */
export async function preflightBountifulOriginalCommandEvidence(ctx,action,principal){
 if(action?.type!=='dnd5e-bountiful-luck')return{ok:true}
 const current=await context(ctx),row=current.combat?.bountifulOriginalParents?.[JSON.stringify(['bountiful-original-parent',action.bountifulLuck?.parentId,action.bountifulLuck?.occurrence])]
 if(!row?.rawIssuer?.rollId?.startsWith('bountiful-plugin-spell-saving-original:')||row.consumed)return{ok:true}
 return preflightBountifulPluginSpellSavingOrPrimaryCommandAppend(ctx,action,principal,damageZeroPorts())
}
